from datetime import date, datetime, timedelta
from pathlib import Path
from urllib.parse import urljoin, urlsplit
from zoneinfo import ZoneInfo

import icalendar
import recurring_ical_events
import requests

import config
import models


def to_local_naive(value):
    """Convert aware timestamps to Zurich, preserving floating timestamps as local time.

    :param value: datetime, either floating or with a time zone
    :return: naive Zurich datetime
    """
    if not isinstance(value, datetime):
        raise ValueError('Timestamp must be a datetime.')
    if value.tzinfo is not None:
        return value.astimezone(ZoneInfo(config.TIMEZONE_NAME)).replace(tzinfo=None)
    return value


def normalize_calendar_link(link):
    """Normalize webcal to HTTPS and reject malformed or insecure calendar links.

    :param link: calendar URL text; surrounding whitespace is ignored
    :return: HTTPS URL, or ValueError for unsupported input
    """
    if not isinstance(link, str):
        raise ValueError('Enter an HTTPS calendar link.')
    link = link.strip()
    if link.lower().startswith('webcal://'):
        link = 'https://' + link[len('webcal://'):]
    try:
        parsed = urlsplit(link)
        if parsed.scheme.lower() != 'https' or not parsed.hostname or parsed.fragment:
            raise ValueError('Invalid calendar link.')
        if any(character.isspace() for character in link):
            raise ValueError('Invalid calendar link.')
        parsed.port
    except ValueError as error:
        raise ValueError('Enter a valid HTTPS calendar link.') from error
    return link


def _decode_calendar(data):
    """Decode a bounded UTF-8 calendar without including its private contents in errors."""
    if not isinstance(data, bytes) or len(data) > config.MAX_CALENDAR_BYTES:
        raise ValueError('Calendar exceeds the allowed file size.')
    try:
        text = data.decode('utf-8-sig')
    except UnicodeError as error:
        raise ValueError('Calendar must be a UTF-8 ICS file.') from error
    if 'BEGIN:VCALENDAR' not in text or not text.rstrip().endswith('END:VCALENDAR'):
        raise ValueError('The file is not a complete ICS calendar.')
    return text


def _response_bytes(response):
    """Read a streamed response while enforcing the byte cap, even without Content-Length."""
    length = response.headers.get('Content-Length')
    if length is not None and int(length) > config.MAX_CALENDAR_BYTES:
        raise ValueError('Calendar exceeds the allowed file size.')
    chunks, total = [], 0
    for chunk in response.iter_content(chunk_size=config.CALENDAR_CHUNK_BYTES):
        total += len(chunk)
        if total > config.MAX_CALENDAR_BYTES:
            raise ValueError('Calendar exceeds the allowed file size.')
        chunks.append(chunk)
    return b''.join(chunks)


def fetch_ics_text(link):
    """Download a verified HTTPS calendar with bounded bytes, redirects and request timeouts.

    :param link: HTTPS or webcal URL, kept out of public error messages
    :return: complete UTF-8 calendar text
    """
    link = normalize_calendar_link(link)
    # Course: A06 – explicit redirect handling prevents an HTTPS-to-HTTP downgrade.
    for attempt in range(config.CALENDAR_MAX_REDIRECTS + 1):
        with requests.get(link, timeout=config.HTTP_TIMEOUT_SECONDS, stream=True,
                          allow_redirects=False) as response:
            if response.is_redirect:
                link = normalize_calendar_link(urljoin(link, response.headers.get('Location', '')))
                continue
            if response.status_code != 200:
                raise ValueError('Calendar server did not return a successful response.')
            return _decode_calendar(_response_bytes(response))
    raise ValueError('Calendar link redirected too many times.')


def _uid_event_id(uid):
    """Validate the exact marker syntax and date, returning an integer ID or None."""
    prefix, separator, domain = str(uid).partition('@')
    if not separator or domain != config.WEEKWISE_UID_DOMAIN:
        return None
    pieces = prefix.split('-')
    if len(pieces) != 3 or pieces[0] != 'weekwise' or not pieces[1].isdigit():
        return None
    try:
        datetime.strptime(pieces[2], config.ICS_DATE_FORMAT)
        event_id = int(pieces[1])
    except ValueError:
        return None
    if len(pieces[2]) != len('YYYYMMDD') or event_id <= 0:
        return None
    return event_id


def extract_weekwise_event_id(uid, description):
    """Recognize the occurrence UID or the exact description marker used by compose links.

    :param uid: event UID, possibly assigned by a calendar provider
    :param description: decoded description containing an optional WeekWise ID line
    :return: positive event ID or None
    """
    event_id = _uid_event_id(uid)
    if event_id is not None:
        return event_id
    for line in str(description).splitlines():
        line = line.strip()
        if line.startswith(config.WEEKWISE_MARKER_PREFIX):
            event_id = _uid_event_id(line[len(config.WEEKWISE_MARKER_PREFIX):])
            if event_id is not None:
                return event_id
    return None


def _range_boundaries(start, end):
    """Convert date boundaries to midnight and validate a positive local query interval."""
    if isinstance(start, date) and not isinstance(start, datetime):
        start = datetime.combine(start, datetime.min.time())
    if isinstance(end, date) and not isinstance(end, datetime):
        end = datetime.combine(end, datetime.min.time())
    start, end = to_local_naive(start), to_local_naive(end)
    if end <= start:
        raise ValueError('Calendar range end must follow its start.')
    return start, end


def _prepare_calendar(text):
    """Parse ICS and omit entries without an explicit end/duration, per SPEC section 9.2."""
    calendar = icalendar.Calendar.from_ical(_decode_calendar(text.encode('utf-8')))
    components = []
    for component in calendar.subcomponents:
        if component.name != 'VEVENT':
            components.append(component)
            continue
        # Keep cancelled recurrence overrides so expansion can suppress their base occurrence.
        if str(component.get('STATUS', '')).upper() == 'CANCELLED':
            recurrence_id = component.decoded('RECURRENCE-ID', None)
            if component.get('DTSTART') is None and recurrence_id is not None:
                # Cancellation notices can omit DTSTART; the expansion library requires it.
                component.add('DTSTART', recurrence_id)
            if component.get('DTSTART') is not None:
                components.append(component)
        elif component.get('DTSTART') is not None:
            if component.get('DTEND') is not None or component.get('DURATION') is not None:
                components.append(component)
    calendar.subcomponents = components
    return calendar


def _all_day(component, start, end, labels, blocks, all_day_busy, range_start, range_end):
    """Expand all-day spans with exclusive DTEND, adding labels and optionally busy windows."""
    day = max(start, range_start.date())
    title = str(component.get('SUMMARY', 'Busy'))
    while day < end and datetime.combine(day, datetime.min.time()) < range_end:
        labels.setdefault(day, []).append(title)
        if all_day_busy:
            beginning = datetime.combine(day, config.DAY_WINDOW_START)
            finish = datetime.combine(day, config.DAY_WINDOW_END)
            if finish > range_start and beginning < range_end:
                blocks.append(models.BusyBlock(beginning, finish, title))
        day += timedelta(days=1)


def parse_calendar(ics_text, range_start, range_end, all_day_busy=False, known_event_ids=None):
    """Reduce ICS occurrences to private in-memory blocks, all-day labels and recognized IDs.

    :param ics_text: decoded calendar text
    :param range_start: inclusive date/datetime boundary
    :param range_end: exclusive date/datetime boundary
    :param all_day_busy: also block the day window for all-day entries
    :param known_event_ids: locally owned IDs whose confirmation state controls busy blocks
    :return: (list of BusyBlock, date-to-labels dictionary, recognized WeekWise ID set)
    """
    range_start, range_end = _range_boundaries(range_start, range_end)
    calendar = _prepare_calendar(ics_text)
    zone = ZoneInfo(config.TIMEZONE_NAME)
    occurrences = recurring_ical_events.of(calendar).between(
        range_start.replace(tzinfo=zone), range_end.replace(tzinfo=zone))
    if len(occurrences) > config.CALENDAR_MAX_OCCURRENCES:
        raise ValueError('Calendar contains too many occurrences in this range.')
    blocks, labels, recognized = [], {}, set()
    known_event_ids = set(known_event_ids or [])
    for component in occurrences:
        _add_component(component, blocks, labels, recognized, known_event_ids,
                       all_day_busy, range_start, range_end)
    blocks.sort(key=lambda block: block.start)
    return blocks, labels, recognized


def _add_component(component, blocks, labels, recognized, known_ids,
                   all_day_busy, range_start, range_end):
    """Apply transparency, cancellation, interval and identity rules to one occurrence."""
    if str(component.get('STATUS', '')).upper() == 'CANCELLED':
        return
    if str(component.get('TRANSP', '')).upper() == 'TRANSPARENT':
        return
    start = component.decoded('DTSTART')
    end = component.decoded('DTEND', None)
    if end is None:
        duration = component.decoded('DURATION', None)
        if duration is None:
            return
        end = start + duration
    if isinstance(start, date) and not isinstance(start, datetime):
        if isinstance(end, datetime) or end <= start:
            raise ValueError('Invalid all-day calendar interval.')
        _all_day(component, start, end, labels, blocks, all_day_busy, range_start, range_end)
        return
    start, end = to_local_naive(start), to_local_naive(end)
    if end <= range_start or start >= range_end:
        return
    event_id = extract_weekwise_event_id(component.get('UID', ''), component.get('DESCRIPTION', ''))
    if event_id is not None:
        recognized.add(event_id)
        if event_id in known_ids:
            return
    title = str(component.get('SUMMARY', 'Busy'))
    if event_id is not None:
        title = config.CALENDAR_UNKNOWN_EVENT_TITLE
    blocks.append(models.BusyBlock(start, end, title, weekwise_event_id=event_id))


def _file_text(path):
    """Read a bounded file without exposing its path or private content in messages."""
    with Path(path).open('rb') as stream:
        return _decode_calendar(stream.read(config.MAX_CALENDAR_BYTES + 1))


def _source_text(mode, link, upload_bytes, demo_file, link_file, upload_file):
    """Load the selected source, using remembered values only when session input is absent."""
    if mode == 'demo':
        return _file_text(demo_file)
    if mode == 'upload':
        return _file_text(upload_file) if upload_bytes is None else _decode_calendar(upload_bytes)
    if link is None:
        link = link_file.read_text(encoding='utf-8')
    return fetch_ics_text(link)


def load_calendar(mode, range_start, range_end, link=None, upload_bytes=None,
                  all_day_busy=False, known_event_ids=None, demo_file=None,
                  private_link_file=None, private_upload_file=None):
    """Load a calendar, falling back to remembered upload then demo without logging secrets.

    :param mode: demo, link or upload
    :param range_start: inclusive date/datetime boundary
    :param range_end: exclusive date/datetime boundary
    :param link: session-only URL; None permits the remembered link
    :param upload_bytes: session-only ICS bytes; None permits the remembered upload
    :param all_day_busy: whether all-day labels also occupy the day window
    :param known_event_ids: IDs owned locally; cancelled exports must not re-block the week
    :param demo_file: optional override of the demo file path
    :param private_link_file: optional override of the remembered link path
    :param private_upload_file: optional override of the remembered upload path
    :return: (busy blocks, all-day labels, recognized IDs, used mode, friendly message)
    """
    if mode not in config.CALENDAR_MODES:
        raise ValueError('Unknown calendar mode.')
    _range_boundaries(range_start, range_end)
    demo_file = Path(demo_file or config.DEMO_CALENDAR_FILE)
    link_file = Path(private_link_file or config.PRIVATE_CALENDAR_LINK_FILE)
    upload_file = Path(private_upload_file or config.PRIVATE_CALENDAR_UPLOAD_FILE)
    candidates = [(mode, link, upload_bytes)]
    if mode != 'demo':
        if upload_file.exists():
            candidates.append(('upload', None, None))
        candidates.append(('demo', None, None))
    for index, (candidate, candidate_link, candidate_bytes) in enumerate(candidates):
        try:
            text = _source_text(candidate, candidate_link, candidate_bytes,
                                demo_file, link_file, upload_file)
            parsed = parse_calendar(text, range_start, range_end, all_day_busy, known_event_ids)
            source_name = config.CALENDAR_MODES[candidate].lower()
            message = '' if index == 0 else (
                f'Could not read your calendar. Showing {source_name} instead.')
            return (*parsed, candidate, message)
        except (OSError, ValueError, TypeError, KeyError, OverflowError, requests.RequestException):
            # Exception text can include the secret URL or private titles; never display it.
            continue
    return [], {}, set(), 'unavailable', 'Could not read any calendar. Free gaps are unavailable.'


def remember_calendar(mode, link=None, upload_bytes=None):
    """Persist the explicitly opted-in source only under git-ignored data/private.

    :param mode: link or upload, selected with explicit Remember opt-in
    :param link: URL to remember when mode is link
    :param upload_bytes: validated ICS bytes to remember when mode is upload
    :return: None
    """
    config.PRIVATE_DIR.mkdir(parents=True, exist_ok=True)
    if mode == 'link':
        link = normalize_calendar_link(link)
        config.PRIVATE_CALENDAR_LINK_FILE.write_text(link, encoding='utf-8')
    elif mode == 'upload':
        _decode_calendar(upload_bytes)
        config.PRIVATE_CALENDAR_UPLOAD_FILE.write_bytes(upload_bytes)
    else:
        raise ValueError('Only calendar links and uploads can be remembered.')


def forget_calendar():
    """Remove only the two explicitly remembered calendar files."""
    for path in (config.PRIVATE_CALENDAR_LINK_FILE, config.PRIVATE_CALENDAR_UPLOAD_FILE):
        path.unlink(missing_ok=True)
